function recordsContent(bookmarked=false){const records=filteredRecords().filter(r=>!bookmarked||state.bookmarks.includes(r.id));return records.length?`<div class="records-grid">${records.map(videoCard).join('')}</div>`:empty(bookmarked?'bookmark':'search',bookmarked?'Keep the good ones close.':'No videos match this search.',bookmarked?'Bookmark a video from your research or library. It will be waiting here.':'Try a different search or import records that match your question.',`<button class="secondary-button" data-view="${bookmarked?'library':'settings'}">${bookmarked?'Explore the library':'Import data'}</button>`);}
function renderLibrary(bookmarked=false){return `<section class="page">${header(bookmarked?'Your little collection.':'Your video library.',bookmarked?'The hooks and ideas you want to come back to.':`${state.records.length} records. ${state.records.every(r=>r.demo)?'Fictional examples to get you started.':'Your imported research, in one place.'}`,bookmarked?'':`<div class="button-row"><button class="secondary-button" data-action="import-creator">Collect creator</button><button class="secondary-button" data-action="import-url">Import URL</button><button class="primary-button" data-action="import">${icon('plus')}Import data</button></div>`)}${filterbar()}<div id="filtered-content">${recordsContent(bookmarked)}</div></section>`;}
function alertMatches(a){return searchRecords(state.records,a.query);}
function renderAlerts(){return `<section class="page">${header('Keep an eye on the good stuff.','Saved searches that refresh as your library grows.',`<button class="primary-button" data-action="new-alert">${icon('plus')}Create alert</button>`)}${state.alerts.length?`<div class="alert-list">${state.alerts.map(a=>`<article class="alert-card">${icon('bell')}<div><h2>${escape(a.query)}</h2><p>${alertMatches(a).length} matching records · ${a.paused?'Paused':'Checks while this app is open'}</p></div><div class="alert-controls"><button class="icon-button" data-run-alert="${escape(a.id)}" aria-label="Run saved search">${icon('search')}</button><button class="icon-button" data-pause-alert="${escape(a.id)}" aria-label="${a.paused?'Resume':'Pause'} alert">${icon(a.paused?'play':'pause')}</button><button class="icon-button" data-delete-alert="${escape(a.id)}" aria-label="Delete alert">${icon('trash')}</button></div></article>`).join('')}</div><p class="small-note">Alerts run in this browser while the app is open. They do not scrape TikTok, run in the background, or send email.</p>`:empty('bell','Good research is worth following.','Save a topic or creator search. When you import matching videos, we will flag the new records here.',`<button class="secondary-button" data-action="new-alert">Create your first alert</button>`)}</section>`;}
function renderSettings(){return `<section class="page">${header('Make this workspace yours.','Your data, your research, your rules.')}<article class="settings-card"><h2>Research library</h2><p>${state.records.length} records are saved in this browser. ${state.records.every(r=>r.demo)?'These are original, fictional examples. Import your own dataset to get research about real videos.':'Your imported data is the source for your research and creator matches.'} Import a JSON array or CSV with handle, caption, hook, format, niche, followers and video metrics.</p><div class="button-row"><button class="primary-button" data-action="import">${icon('plus')}Import JSON / CSV</button><button class="secondary-button" data-action="export-library">${icon('download')}Export library</button><button class="secondary-button" data-action="import-creator">Collect creator</button><button class="secondary-button" data-action="import-url">Import TikTok URL</button><button class="secondary-button" data-action="add-record">Add a video record</button></div><p class="small-note">Import replaces the library after validation. Attach a video for sampled-frame visual feedback. Direct URL import retrieves public metadata; captions are not transcripts.</p></article><article class="settings-card"><h2>Research engine</h2><p>${aiStatus.providerConfigured?'An AI provider is configured on this server. Synthesis stays grounded in the records retrieved from your library.':'Local library research is ready. Keyword retrieval, creator filters, hook comparisons and format analysis work without an API key. For AI synthesis, configure a model provider on your server.'}</p><pre>OPENAI_API_KEY=your-provider-key\nOPENAI_BASE_URL=https://api.openai.com/v1\nOPENAI_MODEL=your-model\nOPENAI_VISION_MODEL=your-vision-model\nOPENREEL_WEB_DISCOVERY=true\nAPIFY_API_TOKEN=optional-keyword-provider-token\nOPENREEL_API_TOKEN=your-private-access-token</pre><div class="button-row"><button class="secondary-button" data-action="set-token">Server access token</button><a class="secondary-button" href="https://github.com/mchdich/openreel-ugc#readme" target="_blank" rel="noopener noreferrer">Read the setup guide ↗</a></div><p class="small-note">Provider keys stay on the server. An access token entered here stays in memory for this tab. Hosting access controls should protect private research.</p></article><article class="settings-card"><h2>A workspace you can take with you</h2><p>Export your chats, bookmarks, alerts and library as a portable JSON backup. You can also restore the original examples for a fresh start.</p><div class="button-row"><button class="secondary-button" data-action="export-workspace">${icon('download')}Export workspace</button><button class="secondary-button" data-action="reset-examples">Restore example library</button></div></article><article class="settings-card"><h2>Open by design</h2><p>OpenReel is an independently written, MIT-licensed recreation inspired by Lightreel's public demo. It includes neither Lightreel's proprietary index nor its source code. Every feature and limitation is documented in the repository.</p><a class="secondary-button" href="https://github.com/mchdich/openreel-ugc" target="_blank" rel="noopener noreferrer">${icon('code')}Explore the source</a></article></section>`;}
function render(){renderSidebar();$('#breadcrumb').textContent=({chat:active()?.title||'Research workspace',trends:'Trends',library:'Video library',bookmarks:'Bookmarks',alerts:'Alerts',settings:'Settings & data'})[view];$('#main').innerHTML=view==='chat'?renderChat():view==='trends'?renderTrends():view==='library'?renderLibrary():view==='bookmarks'?renderLibrary(true):view==='alerts'?renderAlerts():renderSettings();$('#engine-status').textContent=aiStatus.providerConfigured?'AI connected':'Local research';}
function navigate(next){if(view==='trends')patterns.leave();view=next;query='';niche='';render();if(next==='trends')patterns.enter(query);closeSidebar();window.scrollTo(0,0);}
function closeSidebar(){$('#sidebar').classList.remove('open');$('#scrim').hidden=true;}
function newChat(){draftText='';conversationReferences.delete(null);sourceMode=defaultSource();sourceSelected=false;attachmentController?.abort();attachmentController=null;attachmentProgress='';if(!busy)pendingVideo?.dispose();pendingVideo=null;state.activeId=null;save();navigate('chat');$('#question')?.focus();}
let pendingChat=null;
async function submit(question){question=question.trim()||(pendingVideo?'Review the visual hook, pacing, and product reveal in this video.':'');if(!question||busy||attachmentProgress)return;if(question.length>6000){toast('Please keep research questions under 6,000 characters.');return;}if(question==='Review my video script'&&!pendingVideo){showModal('Make your next video better.',`<p>Paste a script, transcript, or shot-by-shot description. OpenReel will compare it with hooks and formats in your library.</p><form id="critique-form"><label for="script-text">Your draft</label><textarea id="script-text" required maxlength="5800" placeholder="Opening: …\nWhat the viewer sees: …\nProduct reveal: …"></textarea><button class="primary-button" type="submit">${icon('spark')}Review my draft</button></form><p class="caption">A transcript is analyzed as text. Use the paperclip to attach actual video for visual analysis. A URL imports metadata only.</p>`);return;}
  let chat=active();if(!chat){chat={id:uid(),title:question.slice(0,49),createdAt:new Date().toISOString(),messages:[],...(['library','corpus','live'].includes(pendingVideo?.returnSource)?{source:pendingVideo.returnSource}:{})};state.conversations.unshift(chat);state.activeId=chat.id;const reference=conversationReferences.get(null);if(reference){conversationReferences.set(chat.id,reference);conversationReferences.delete(null);}}
  const history=chat.messages.slice(-10).map(m=>({role:m.role,content:(m.role==='user'?m.content:resultText(m.result)).slice(0,6000)}));
  const resolvedQuestion=researchQuery(question,history);
  const reference=wantsSimilarity(resolvedQuestion)?conversationReferences.get(chat.id):null;
  const referenceInput=reference?{referenceId:reference.id,referenceRecord:reference}:{};
  const requestSource=sourceMode,requestMode=researchMode;if(requestSource!=='video'||conversationVideos.has(chat.id))rememberSource(chat,requestSource);const explicitAttachment=pendingVideo;const followupVideo=requestSource==='video'?conversationVideos.get(chat.id):null;const attached=explicitAttachment||followupVideo;let requestRecords=requestSource==='corpus'?[]:researchLibrary(),discoveryNotice='';draftText='';chat.messages.push({role:'user',content:question,...(attached?{attachment:{name:attached.attachment.name,duration:attached.attachment.duration}}:{})});busy=true;pendingChat=chat.id;view='chat';updateResearchProgress(chat.id,{source:requestSource,mode:requestMode,stage:attached?'Reviewing sampled video frames…':requestSource==='live'?'Finding TikTok videos…':requestSource==='corpus'?'Searching indexed videos…':'Researching your library…'});save();render();window.scrollTo(0,document.body.scrollHeight);
  try{
    const chatBudget=aiStatus?.providerConfigured===true&&Number.isInteger(aiStatus.chatRequestTimeoutMs)&&aiStatus.chatRequestTimeoutMs>=10000&&aiStatus.chatRequestTimeoutMs<=180000?aiStatus.chatRequestTimeoutMs:25000;
    // Optional public-post checks add at most20s beside Live's existing allowance.
    const liveBudget=aiStatus.postMetadataConfigured===true?60000:40000;
    const requestBudget=attached?.sourceReview?245000:attached?185000+(attached.audio?.chunks?.length||0)*45000:Math.max(65000,chatBudget+(requestSource==='live'?liveBudget:5000));
    const controller=new AbortController();const timeout=setTimeout(()=>controller.abort(),requestBudget);let res;
    try{
      if(attached?.audio?.status==='available'&&!attached.attachment.transcript){
        attached.transcriptions||=[];
        for(let i=0;i<attached.audio.chunks.length;i++){updateResearchProgress(chat.id,{stage:`Transcribing audio… ${i+1}/${attached.audio.chunks.length}`});if(attached.transcriptions[i]===undefined){const result=await apiRequest('/api/audio/transcribe',{audio:attached.audio.chunks[i]},controller.signal);attached.transcriptions[i]=result.text;}}
        attached.attachment.transcript=attached.transcriptions.join(' ').slice(0,12000);
        updateResearchProgress(chat.id,{stage:'Reviewing sampled video frames…'});
      }
      if(!attached&&requestSource==='live'){
        if(resolvedQuestion.length>1000)throw new Error('Live search supports up to 1,000 characters of combined criteria. Shorten the request before searching again.');
        const found=await apiRequest('/api/videos/discover',{query:resolvedQuestion,limit:requestMode==='deep'?30:15,...referenceInput},controller.signal);
        if(!Array.isArray(found.records))throw new Error('Live search returned invalid video records.');
        const real=found.records.length?normalizeRecords(found.records).filter(r=>!r.demo):[];if(!real.length)throw new Error('Live search returned no real video records. No example data was used.');
        state.records=mergeLibrary(state.records,real,{dropExamples:true});
        const mergedRecords=new Map(state.records.map(record=>[record.id,record]));
        requestRecords=real.map(record=>mergedRecords.get(record.id));
        discoveryNotice=[typeof found.notice==='string'?found.notice:'',typeof found.provider==='string'&&found.provider.trim()?`Discovery provider: ${found.provider.slice(0,200)}.`:'',Number.isSafeInteger(found.creatorsRefreshed)&&found.creatorsRefreshed>=0?`Public creator profiles refreshed: ${found.creatorsRefreshed}.`:''].filter(Boolean).join(' ');
        updateResearchProgress(chat.id,{stage:'Researching retrieved videos…',records:real});
      }
      res=await fetch(attached?.sourceReview?'/api/videos/analyze':attached?'/api/video/analyze':'/api/chat',{method:'POST',headers:{'Content-Type':'application/json',...(apiToken?{Authorization:`Bearer ${apiToken}`}:{})},body:JSON.stringify(attached?{question:!explicitAttachment&&followupVideo?(`Follow-up: ${question}\n\nPrior discussion (context only):\n${history.slice(-4).map(m=>m.role+': '+m.content).join('\n')}`).slice(0,6000):question,...(attached.sourceReview?(attached.sessionId?{sessionId:attached.sessionId}:{url:attached.sourceUrl}):{attachment:attached.attachment})}:{question,records:requestRecords,history,mode:requestMode,corpus:requestSource==='corpus',...referenceInput}),signal:controller.signal});
    }finally{clearTimeout(timeout);}
    if(!res.ok){let data={};try{data=await res.json()}catch{}throw new Error(res.status===401?'This server requires an access token. Add it in Settings, then send your question again.':data.error||`Research request failed (${res.status}). Please try again.`);}
    const result=await res.json();if(!result||typeof result.title!=='string')throw new Error('The server returned an invalid response.');
    if(discoveryNotice)result.notice=[discoveryNotice,typeof result.notice==='string'?result.notice:''].filter(Boolean).join(' ');
    if(attached?.sourceReview){if(typeof result.sourceSessionId!=='string'||!result.videoAnalysis?.sourceEvidence)throw new Error('The source review returned incomplete capture evidence.');attached.sessionId=result.sourceSessionId;attached.frameCount=result.videoAnalysis.frameCount;attached.attachment={name:result.videoAnalysis.name,duration:result.videoAnalysis.duration};delete result.sourceSessionId;const message=chat.messages.at(-1);if(message?.role==='user')message.attachment={name:attached.attachment.name,duration:attached.attachment.duration};}
    chat.messages.push({role:'assistant',researchSource:attached?'video':requestSource,result});if(attached){if(explicitAttachment){watchedToday++;try{localStorage.setItem('openreel.watched.v1',JSON.stringify({date:new Date().toISOString().slice(0,10),count:watchedToday}));}catch{}const old=conversationVideos.get(chat.id);if(old&&old!==attached)old.dispose();conversationVideos.set(chat.id,attached);rememberSource(chat,'video');if(state.activeId===chat.id)sourceMode='video';while(conversationVideos.size>2){const oldest=conversationVideos.keys().next().value;conversationVideos.get(oldest).dispose();conversationVideos.delete(oldest);if(conversationSources.get(oldest)==='video')conversationSources.delete(oldest);}if(pendingVideo===explicitAttachment)pendingVideo=null;attached.audio=null;attached.transcriptions=null;}}
  }catch(error){if(explicitAttachment&&pendingVideo!==explicitAttachment)explicitAttachment.dispose();chat.messages.push({role:'assistant',researchSource:attached?'video':requestSource,error:error.name==='AbortError'?'Research took too long. Please try a smaller library or question.':error.message});}
  finally{busy=false;pendingChat=null;if(researchProgress?.chatId===chat.id)researchProgress=null;save();render();if(view==='chat'&&state.activeId===chat.id){$('#question')?.focus();$('.chat-composer')?.scrollIntoView({block:'end',behavior:'smooth'});}}
}
function resultText(r){if(!r)return '';return `${r.title}\n\n${r.summary}\n\n${(r.sections||[]).map(s=>`${s.heading}\n${s.text}`).join('\n\n')}${r.notice?`\n\n${r.notice}`:''}`;}
function exportFile(name,data,type='application/json'){const blob=new Blob([typeof data==='string'?data:JSON.stringify(data,null,2)],{type});const object=URL.createObjectURL(blob);const a=document.createElement('a');a.href=object;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(object),1000);}
function exportChat(id){const chat=state.conversations.find(c=>c.id===id);if(chat)exportFile('openreel-research.txt',chat.messages.map(m=>m.role==='user'?`YOU\n${m.content}`:`OPENREEL\n${m.error||resultText(m.result)}`).join('\n\n──────────\n\n'),'text/plain');}
function sourceCaptureSummary(video){const e=video?.sourceEvidence;return e?`<p class="small-note">Public-player samples at ${escape(e.frames.map(f=>f.timestamp+'s').join(', '))} · captured ${escape(e.observedAt.slice(0,10))} · <a href="${escape(url(e.sourceUrl))}" target="_blank" rel="noopener noreferrer">Source ↗</a></p>`:'';}
function reviewSourceRecord(id){if(busy||!aiStatus.sourceVideoAvailable)return;const record=findRecord(id);if(!record||record.demo||!/^https:\/\/www\.tiktok\.com\/@[^/]+\/video\/\d+$/.test(record.url))return;$('#modal').close();newChat();pendingVideo={sourceReview:true,sourceUrl:record.url,attachment:{name:displayHandle(record.handle,record.creatorId),duration:0},returnSource:sourceMode,dispose(){}};sourceMode='video';submit('Review the visual hook, visible sequence and product reveal. Give three concrete editing suggestions grounded in the sampled frames.');}
function visualCaptureDetails(r){const e=r.visualEvidence;if(r.descriptionSource!=='openreel-vision'||!e)return '';return `<p class="small-note">Captured ${escape(e.observedAt.slice(0,10))} · ${e.frames.length} cited frame samples at ${escape(e.frames.map(f=>f.timestamp+'s').join(', '))} of ${escape(String(Math.round(e.duration*100)/100))}s. <a href="${escape(url(e.sourceUrl))}" target="_blank" rel="noopener noreferrer">Frame source ↗</a>. This description covers sampled images; no audio was analyzed.</p>`;}
function recordModal(id){const r=findRecord(id);if(!r)return;showModal(displayHandle(r.handle,r.creatorId),`${r.demo?'<span class="pill-label">FICTIONAL EXAMPLE RECORD</span>':''}<h3>${escape(r.hook||r.caption||'Video record')}</h3><div class="record-metrics"><div><strong>${metric(r,'views')}</strong><span>Views</span></div><div><strong>${metric(r,'followers')}</strong><span>Followers</span></div><div><strong>${engagementText(r)}</strong><span>Engagement</span></div></div><p class="small-note">Posting date: <time datetime="${escape(r.postedAt)}" title="${escape(r.postedAt)}">${escape(postingDateLabel(r))}</time>${r.postingEvidence?` · <a href="${escape(r.postingEvidence.url)}" target="_blank" rel="noopener noreferrer">Date source</a> observed ${escape(r.postingEvidence.observedAt.slice(0,10))}`:''}</p><p>${escape(r.caption)}</p><h3>Transcript / content notes</h3><p>${escape(r.transcript||'No transcript provided. Import one to enable content-specific feedback.')}</p>${r.visualDescription?`<h3>${escape(descriptionLabel(r))}</h3><p>${escape(r.visualDescription)}</p>${visualCaptureDetails(r)}`:''}<h3>Creator details</h3><p>${escape([displayHandle(r.handle,r.creatorId),r.niche,r.location,r.school,r.email].filter(Boolean).join(' · '))}</p><div class="button-row">${aiStatus.sourceVideoAvailable&&!r.demo&&/^https:\/\/www\.tiktok\.com\/@[^/]+\/video\/\d+$/.test(r.url)?`<button class="primary-button" data-review-source="${escape(r.id)}" ${busy?'disabled':''}>${icon('spark')}Review video</button>`:''}<button class="secondary-button" data-similar-record="${escape(r.id)}" ${busy?'disabled':''}>${icon('people')}Find similar creators</button><button class="secondary-button" data-bookmark="${escape(r.id)}">${icon('bookmark')}${state.bookmarks.includes(r.id)?'Remove bookmark':'Bookmark record'}</button>${url(r.url)?`<a class="primary-button" href="${escape(url(r.url))}" target="_blank" rel="noopener noreferrer">Open original source ↗</a>`:''}</div>`);}
function parseCSV(text){const rows=[];let row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){cell+='"';i++;}else quoted=!quoted;}else if(c===','&&!quoted){row.push(cell);cell='';}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(cell);if(row.some(v=>v.trim()))rows.push(row);row=[];cell='';}else cell+=c;}if(quoted)throw new Error('CSV contains an unclosed quoted field.');row.push(cell);if(row.some(v=>v.trim()))rows.push(row);if(rows.length<2)throw new Error('CSV needs a header row and at least one video.');const headers=rows.shift().map(h=>h.trim());return rows.map((r,index)=>{if(r.length!==headers.length)throw new Error(`CSV row ${index+2} has ${r.length} columns; expected ${headers.length}.`);return Object.fromEntries(headers.map((h,i)=>[h,r[i]]));});}
function importData(records){const normalized=normalizeRecords(records);if(!normalized.length)throw new Error('The import has no video records.');state.records=normalized;state.bookmarks=state.bookmarks.filter(id=>normalized.some(r=>r.id===id));checkAlerts(true);save();navigate('library');toast(`Imported ${normalized.length} video records.`);}
function checkAlerts(announce=false){for(const a of state.alerts){if(a.paused)continue;const matches=alertMatches(a).map(r=>r.id),seen=new Set(a.seen||[]);const fresh=matches.filter(id=>!seen.has(id));if(announce&&fresh.length)toast(`${fresh.length} new matching records for “${a.query}”.`);a.seen=matches;}save();}
