 if(f.id==='creator-form'){const button=f.querySelector('button');button.disabled=true;apiRequest('/api/videos/creator',{handle:$('#creator-handle').value}).then(found=>{if(!found.records.length)throw new Error(found.notice||'No public videos are available for this creator.');state.records=mergeLibrary(state.records,found.records,{dropExamples:true});save();$('#modal').close();navigate('library');toast(`Collected ${found.records.length} public video records.`);}).catch(err=>{toast(err.message);button.disabled=false;});}
