 if(f.id==='video-transcript-form'&&pendingVideo){pendingVideo.attachment.transcript=$('#video-transcript').value.trim();$('#modal').close();render();}
 if(f.id==='token-form'){apiToken=$('#server-token').value.trim();$('#modal').close();toast('Access token set for this tab.');}
